import{createChecklist as f,setPreferences as b,addRoom as v,addItem as g,setSettings as x}from"./store.min.js";export const EXAMPLE_ID="example-home-1";const p=[["main","entry","",[{task:"mop-floor",size:"small"},{task:"shoe-area"}]],["main","kitchen","",[{task:"stovetop",options:["deep-clean"],important:!0,notes:"The grates can soak in the sink while you do the rest."},{task:"countertops",options:["disinfect"]},{task:"kitchen-sink",options:["polish"]},{task:"microwave"},{task:"mop-floor",options:["under-furniture"]}]],["main","living","",[{task:"tidy-room",size:"large"},{task:"vacuum-floor",size:"large",avoid:"Please skip the wool rug by the fireplace."},{task:"upholstery",quantity:2,notes:"Juniper sheds on the gray sofa."}]],["main","dining","",[{task:"table-chairs"}]],["main","office","",[{task:"desk",notes:"Please leave the papers where they are."},{task:"vacuum-floor",size:"small"}]],["main","powder-room","",[{task:"toilet"},{task:"bathroom-sink"}]],["second","primary-bedroom","",[{task:"change-linens",quantity:1,important:!0},{task:"vacuum-floor"}]],["second","primary-bathroom","",[{task:"shower",options:["descale"],important:!0,avoid:"No abrasives on the glass, please."},{task:"toilet",options:["deep-clean"]},{task:"bathroom-sink"},{task:"mirrors",quantity:2}],"shower"],["second","bedroom","Emma's room",[{task:"make-bed",quantity:1}]],["second","bedroom","Noah's room",[{task:"make-bed",quantity:1}]],["second","bedroom","Guest room",[{task:"change-linens",quantity:1}]],["second","bathroom","Hall bath",[{task:"toilet"},{task:"bathtub"}]],["basement","family","Basement family room",[{task:"vacuum-floor",size:"large"}]]];export function withExample(n,o,s,d){const a=[e=>f(e,{title:"Example home",levels:["basement","main","second"],visitFrequency:"biweekly",household:"Parking in the driveway. Supplies are under the kitchen sink."},o,s,{id:EXAMPLE_ID,sample:!0}),e=>b(e,EXAMPLE_ID,{keys:["pet-safe","pets-home"],note:"Our dog, Juniper, is friendly and stays in the yard during visits."},o,s)];p.forEach(([e,t,k,u,h],m)=>{const l=`example-room-${m+1}`;a.push(i=>v(i,EXAMPLE_ID,{level:e,area:t,label:k,bath:h},o,s,{id:l,sample:!0})),u.forEach((i,c)=>{a.push(y=>g(y,EXAMPLE_ID,{...i,roomId:l},o,s,{id:`example-task-${m+1}-${c+1}`,sample:!0,check:d}))})});let r=n;for(const e of a){const t=e(r);if(t.error)return{doc:n,error:t.error};r=t.doc}return{doc:x(r,{activeId:EXAMPLE_ID}).doc,error:null}}export const __test__={ROOMS:p};
